<script setup>
import {onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {approveRefund,getAdminRefund,rejectRefund} from '../../api/refund'
const route=useRoute(),router=useRouter(),data=ref({}),loading=ref(false),auditing=ref(false);const load=async()=>{loading.value=true;try{data.value=(await getAdminRefund(route.params.id)).data}finally{loading.value=false}};const audit=async approved=>{const {value}=await ElMessageBox.prompt('请输入审核意见',approved?'审核通过':'审核驳回',{inputType:'textarea',inputValidator:v=>!v||v.length<=500||'最多500字'});auditing.value=true;try{data.value=(await (approved?approveRefund(route.params.id,value):rejectRefund(route.params.id,value))).data;ElMessage.success('审核完成')}finally{auditing.value=false}};onMounted(load)
</script>
<template><el-card v-loading="loading"><template #header><el-page-header @back="router.push('/admin/refunds')"><template #content>退票审核详情</template></el-page-header></template><el-descriptions v-if="data.refundId" :column="2" border><el-descriptions-item label="退款编号">{{data.refundNo}}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag :value="data.refundStatus"/></el-descriptions-item><el-descriptions-item label="用户">{{data.username}}</el-descriptions-item><el-descriptions-item label="订单号">{{data.orderNo}}</el-descriptions-item><el-descriptions-item label="比赛">{{data.homeClubName}} vs {{data.awayClubName}}</el-descriptions-item><el-descriptions-item label="退款金额">{{$formatMoney(data.refundAmount)}}</el-descriptions-item><el-descriptions-item label="申请时间">{{$formatDateTime(data.appliedAt)}}</el-descriptions-item><el-descriptions-item label="审核时间">{{$formatDateTime(data.auditedAt)}}</el-descriptions-item><el-descriptions-item label="申请原因" :span="2">{{data.reason}}</el-descriptions-item><el-descriptions-item label="审核意见" :span="2">{{data.auditReason||'—'}}</el-descriptions-item></el-descriptions><el-table v-if="data.tickets" :data="data.tickets" class="tickets" empty-text="暂无电子票"><el-table-column prop="ticketCode" label="票码"/><el-table-column prop="rowNo" label="排"/><el-table-column prop="seatNo" label="座"/><el-table-column label="电子票状态"><template #default="{row}"><StatusTag :value="row.ticketStatus"/></template></el-table-column></el-table><div v-if="data.refundStatus==='PENDING'" class="actions"><el-button type="success" :loading="auditing" @click="audit(true)">审核通过</el-button><el-button type="danger" :loading="auditing" @click="audit(false)">审核驳回</el-button></div></el-card></template>
<style scoped>.tickets,.actions{margin-top:16px}.actions{display:flex;gap:10px}</style>
